# -*- coding: utf-8 -*-
# 第 11 批（B4）：高壓氣體勞工安全規則（111/9/14）第179條～第229條 補題
HG = "OSH-41"
Q = [
(HG,"第179條",2,"高壓氣體-消費",
 "操作可燃性氣體、毒性氣體及氧氣之灌氣容器等之閥，應準用何項規定？",
 ["準用考慮閥之材料構造使用狀況以防止過巨之力加諸於閥上並訂入工作守則之規定","準用容器應保持溫度攝氏四十度以下並設溫度計或可檢知溫度計測裝置之規定","準用配管應採熔接接合並依氣體性狀於必要處所採二重管構造之相關各項規定","準用容器不得有腐蝕裂隙裂痕皺紋且應無漏氣並標示有效期限之相關各項規定"],"a",
 "第179條：操作可燃性氣體、毒性氣體及氧氣（可燃性氣體等）之灌氣容器等之閥，準用第175條之規定，即應考慮該閥之材料、構造及使用狀況，採取必要之措施以防止過巨之力加諸於閥上，並訂入工作守則中。第216條對廢棄時之灌氣容器等閥類亦準用第175條。",
 "Which rule applies by reference when operating valves of filled cylinders of flammable, toxic or oxygen gas?",
 ["The rule on considering valve material, construction and condition to avoid excessive force, written into work rules","The rule on keeping container temperature at or below 40 degrees with a thermometer or measuring device fitted","The rule on welding piping joints and using double-pipe construction where the gas properties require it","The rule on cylinders being free of corrosion, cracks and leaks and carrying a validity period marking"],
 "Article 179, applying Article 175."),

(HG,"第180條",2,"高壓氣體-消費",
 "加熱灌氣容器等、閥或配管時，應使用何種方式？何者不在此限？",
 ["應使用熱濕布或溫度攝氏四十度以下之溫水；設有安全閥及自動控制之加熱器內配管除外","應使用蒸汽管或溫度攝氏一百度以下之熱水；設有壓力表及手動控制之加熱器配管除外","應使用電熱毯或溫度攝氏六十度以下之溫風；設有液面計及緊急遮斷裝置之配管除外","應使用紅外線燈或溫度攝氏八十度以下之熱媒；設有防波板及逆止閥之容器配管除外"],"a",
 "第180條：加熱灌氣容器等、閥或配管時，應使用熱濕布或溫度在攝氏四十度以下之溫水；但設有安全閥及可調節壓力或溫度之自動控制之加熱器內之配管，不在此限。第97條第三款、第217條、第78條第六款亦有相同之熱濕布或攝氏四十度以下溫水規定。",
 "How may filled cylinders, valves or piping be heated, and what is excluded?",
 ["Hot wet cloth or warm water at or below 40 C; piping inside heaters with safety valves and automatic control excluded","Steam pipes or hot water at or below 100 C; piping inside heaters with pressure gauges and manual control excluded","Electric blankets or warm air at or below 60 C; piping fitted with level gauges and emergency shut-off excluded","Infrared lamps or heat medium at or below 80 C; container piping fitted with baffles and check valves excluded"],
 "Article 180; compare Articles 97, 217 and 78."),

(HG,"第181條",2,"高壓氣體-消費",
 "可燃性氣體或毒性氣體之消費，應在何種場所為之？容器溫度應如何保持？",
 ["應在通風良好之場所為之；且應保持其容器在攝氏四十度以下","應在密閉負壓之場所為之；且應保持其容器在攝氏五十度以下","應在具防爆構造場所為之；且應保持其容器在攝氏三十度以下","應在設有防液堤場所為之；且應保持其容器在攝氏六十度以下"],"a",
 "第181條：可燃性氣體或毒性氣體之消費，應在通風良好之場所為之，且應保持其容器在攝氏四十度以下。第190條對一般液化石油氣之消費、第116條第一款對以容器儲存可燃性或毒性氣體、第79條第九款對容器放置場均有通風良好或攝氏四十度以下之規定。第242條定本條不適用於液化石油氣。",
 "Where must flammable or toxic gas be consumed, and at what container temperature?",
 ["In a well-ventilated place; containers kept at or below 40 degrees Celsius","In a sealed negative-pressure place; containers kept at or below 50 degrees","In an explosion-proof structure place; containers kept at or below 30 degrees","In a place provided with a liquid dike; containers kept at or below 60 degrees"],
 "Article 181; compare Articles 79, 116 and 190."),

(HG,"第182條",3,"高壓氣體-消費",
 "氰化氫之消費，對灌裝日期有何限制？何種情形不在此限？",
 ["應使用灌裝於容器後不超過六十日者；純度百分之九十八以上且未著色者不在此限","應使用灌裝於容器後不超過三十日者；純度百分之九十以上且未著色者不在此限","應使用灌裝於容器後不超過九十日者；純度百分之九十五以上且已著色者不在此限","應使用灌裝於容器後不超過一百八十日者；純度百分之九十九以上且已著色者除外"],"a",
 "第182條：氰化氫之消費，應使用灌裝於容器後不超過六十日者；但純度在百分之九十八以上，且未著色者，不在此限。第116條第三款對氰化氫之儲存、第97條第四款對氰化氫移注他容器均有相同之六十日與百分之九十八規定；第72條第三款並定氰化氫灌氣容器應於灌裝後靜置二十四小時以上確認無漏洩。",
 "What time limit applies to consuming hydrogen cyanide, and what is excepted?",
 ["It must be used within 60 days of filling; purity of 98 percent or more and uncoloured is excepted","It must be used within 30 days of filling; purity of 90 percent or more and uncoloured is excepted","It must be used within 90 days of filling; purity of 95 percent or more and coloured is excepted","It must be used within 180 days of filling; purity of 99 percent or more and coloured is excepted"],
 "Article 182; compare Articles 72, 97 and 116."),

(HG,"第183條",3,"高壓氣體-消費",
 "環氧乙烷之消費，應於事前如何處理？其配管應設何種裝置？",
 ["應事前以氮氣或二氧化碳置換設備內部氣體；容器與消費設備間之配管應設逆流防止裝置","應事前以空氣或氧氣置換設備內部氣體；容器與消費設備間之配管應設緊急遮斷裝置","應事前以水蒸氣或熱水沖洗設備內部；容器與消費設備間之配管應設過流防止之閥類","應事前以稀酸或鹼液中和設備內部；容器與消費設備間之配管應設二重管構造之保護"],"a",
 "第183條：環氧乙烷之消費，應於事前以氮氣或二氧化碳置換設備內部之氣體，且在環氧乙烷容器與消費所使用之設備間之配管，設逆流防止裝置。第71條第五款對環氧乙烷灌注、第72條第四款及第五款對環氧乙烷儲槽與灌氣容器亦有以氮或二氧化碳置換之規定。",
 "How must ethylene oxide consumption be prepared, and what device must the piping have?",
 ["Purge the equipment with nitrogen or carbon dioxide beforehand; fit a backflow prevention device in the piping","Purge the equipment with air or oxygen beforehand; fit an emergency shut-off device in the connecting piping","Flush the equipment with steam or hot water beforehand; fit an excess flow prevention valve in the piping","Neutralise the equipment with dilute acid or alkali first; provide double-pipe protection for the piping"],
 "Article 183; compare Articles 71 and 72."),

(HG,"第184條",2,"高壓氣體-消費",
 "距可燃性氣體或氧氣之消費設備多少範圍內應嚴禁煙火，且不得放置危險性物質？",
 ["五公尺以內，但該設備內所使用者除外","二公尺以內，但該設備內所使用者除外","八公尺以內，但該設備內所使用者除外","十公尺以內，但該設備內所使用者除外"],"a",
 "第184條：距可燃性氣體或氧氣之消費設備五公尺以內，應嚴禁煙火（該設備內所使用者除外），且不得放置危險性物質。第169條對儲存相關設備四周五公尺以內亦有相同規定；第79條第八款則對容器放置場四周二公尺以內定禁煙火及禁放危險性物質。",
 "Within what distance of flammable gas or oxygen consumption equipment are flames and dangerous substances banned?",
 ["Within five metres, except those used inside the equipment","Within two metres, except those used inside the equipment","Within eight metres, except those used inside the equipment","Within ten metres, except those used inside the equipment"],
 "Article 184; compare Articles 79 and 169."),

(HG,"第185條",2,"高壓氣體-消費",
 "氧氣之消費所使用之閥或器具，應如何處理後始得使用？",
 ["非除卻石油類、油脂類及其他可燃性物質後，不得使用","非以氮氣或二氧化碳置換其內部氣體後，不得使用","非經實施音響檢查及內部檢查合格後，不得使用","非以熱濕布或攝氏四十度以下溫水加熱後，不得使用"],"a",
 "第185條：氧氣之消費所使用之閥或器具，非除卻石油類、油脂類及其他可燃性物質後，不得使用。第170條對消費液氧、第214條對氧氣之廢棄、第97條第二款對灌注氧氣於容器均有相同之除卻石油類油脂類要求，第97條第二款並定容器與閥間不得使用可燃性墊圈。",
 "How must valves or appliances for oxygen consumption be treated before use?",
 ["They may not be used until petroleum, oils and fats and other combustibles are removed","They may not be used until their interior has been purged with nitrogen or carbon dioxide","They may not be used until they have passed a sound check and an internal inspection","They may not be used until warmed with hot wet cloth or warm water at or below 40 C"],
 "Article 185; compare Articles 97, 170 and 214."),

(HG,"第186條",2,"高壓氣體-消費",
 "可燃性氣體、毒性氣體及氧氣於消費後，應如何處理？",
 ["應嚴閉其閥，並採取防止容器翻倒及損傷其閥之措施","應開啟其閥洩壓，並採取容器分區放置與標示之措施","應以氮氣置換內部，並採取容器加鎖及鉛封之措施","應立即送回供應事業單位，並採取運輸檢點之措施"],"a",
 "第186條：可燃性氣體等應於消費後嚴閉其閥，並採取防止容器翻倒及損傷其閥之措施。第215條對廢棄後亦有完全相同之規定；第79條第十款對容器放置場之灌氣容器等（內容積五公升以下者除外）亦要求採防止翻倒掉落引起衝擊及損傷附屬閥之措施。",
 "What must be done after flammable, toxic or oxygen gas has been consumed?",
 ["Close the valves tightly and take measures preventing the container toppling or valve damage","Open the valves to release pressure and take measures for separate placement and marking","Purge the interior with nitrogen and take measures locking and lead-sealing the containers","Return them to the supply enterprise at once and take transport inspection measures first"],
 "Article 186; identical to Article 215."),

(HG,"第187條、第188條",2,"高壓氣體-消費",
 "從事高壓氣體消費設備之修理或清掃時，應如何辦理？終了後又如何？",
 ["應事前以不易與內部氣體反應之氣體或液體置換；終了後未確認可正常安全運轉前不得消費","應事前以空氣直接吹除內部殘氣；終了後即可立即恢復消費，無須另行確認運轉狀況","應事前報請勞動檢查機構派員到場監督；終了後應由檢查機構發給合格證後始得消費","應事前將設備拆解並送廠外清洗；終了後應重新實施構造檢查及耐壓試驗始得消費"],"a",
 "第187條：從事高壓氣體消費設備之修理或清掃時，應於事前以不易與其內部氣體反應之氣體或液體置換其內部之氣體等防止危險措施後為之，且於其修理或清掃終了後，未確認該設施可正常安全運轉前，不得從事消費。第75條對氣體設備之修理等相關作業有更完整之規定。第188條已刪除。",
 "How must repair or cleaning of high-pressure gas consumption equipment be carried out and concluded?",
 ["Purge beforehand with gas or liquid unreactive with the contents; no consumption until safe operation is confirmed","Blow out residual gas directly with air beforehand; consumption may resume at once without confirming operation","Report beforehand so the labour inspection agency supervises; consumption only after it issues a certificate","Dismantle and clean the equipment off site beforehand; consumption only after fresh construction and pressure tests"],
 "Article 187 (Article 188 deleted); compare Article 75."),

(HG,"第189條",2,"高壓氣體-消費",
 "可燃性氣體、毒性氣體及氧氣之消費，除第一百七十九條至第一百八十七條規定外，準用何項規定？",
 ["準用特定高壓氣體消費設施自境界警戒標示至操作閥防止過巨之力等一系列規定","準用固定於車輛之容器運輸自防波板至運輸開始終止檢點等一系列之相關規定","準用甲類製造事業單位加氣站自承受灌裝車輛距離至添加臭劑等一系列之規定","準用冷凍機器容器自超音波探傷檢查至浸透探傷試驗等一系列之相關各項規定"],"a",
 "第189條：可燃性氣體等之消費，除依第179條至第187條規定外，準用第154條至第175條之規定，即特定高壓氣體消費設施之境界警戒標示、廠房構造、材料、基礎、耐壓與氣密試驗、厚度、壓力表與安全裝置、逆流防止裝置、低溫儲槽、除毒措施、熔接接合、二重管、靜電、漏洩警報、消防設備、五公尺禁煙火、液氧除油、閥操作、修理作業、沈陷注意等規定。",
 "Besides Articles 179 to 187, which rules apply to consuming flammable, toxic or oxygen gas?",
 ["The specified high-pressure gas consumption rules from boundary warning signs through to valve operating force","The vehicle-mounted container transport rules from baffle plates through to start and end of transport checks","The Class A filling station rules from vehicle distance for filling through to the addition of odorant to gas","The refrigeration container rules from ultrasonic testing through to the penetrant testing requirements"],
 "Article 189, applying Articles 154 to 175."),

(HG,"第190條",2,"高壓氣體-液化石油氣",
 "一般液化石油氣之消費，應於何種處所為之？灌氣容器等溫度應如何保持？",
 ["應於通風良好之處所為之；其灌氣容器等之溫度應保持於攝氏四十度以下","應於密閉負壓之處所為之；其灌氣容器等之溫度應保持於攝氏五十度以下","應於具防爆構造處所為之；其灌氣容器等之溫度應保持於攝氏三十度以下","應於設有防液堤處所為之；其灌氣容器等之溫度應保持於攝氏六十度以下"],"a",
 "第190條：一般液化石油氣之消費應於通風良好之處所為之，且其灌氣容器等之溫度應保持於攝氏四十度以下。第30條定一般液化石油氣消費事業單位為特定液化石油氣消費事業單位以外者；第181條對可燃性氣體或毒性氣體之消費亦有通風良好與攝氏四十度以下之規定。",
 "Where must general LPG be consumed, and at what temperature must filled cylinders be kept?",
 ["In a well-ventilated place; filled cylinders kept at or below 40 degrees Celsius","In a sealed negative-pressure place; filled cylinders kept at or below 50 degrees","In an explosion-proof structure place; filled cylinders kept at or below 30 degrees","In a place provided with a liquid dike; filled cylinders kept at or below 60 degrees"],
 "Article 190; compare Articles 30 and 181."),

(HG,"第191條",1,"高壓氣體-液化石油氣",
 "一般液化石油氣之消費後，應採取何種措施？",
 ["應採取防止損傷閥等之措施","應採取容器分區標示之措施","應採取以氮氣置換之措施","應採取立即送回供應商措施"],"a",
 "第191條：一般液化石油氣之消費後應防止損傷閥等之措施。第186條對可燃性氣體等之消費後則定應嚴閉其閥並採取防止容器翻倒及損傷其閥之措施；第191條之1並對液化石油氣容器串接供廠場使用另定總容量一千公斤以下等管理規定。",
 "What measure must be taken after general LPG has been consumed?",
 ["Measures preventing damage to the valves","Measures marking containers by separate zone","Measures purging the container with nitrogen","Measures returning containers to the supplier"],
 "Article 191; compare Articles 186 and 191-1."),

(HG,"第192條",2,"高壓氣體-液化石油氣",
 "一般液化石油氣之消費，除第一百九十條至第一百九十一條之一規定外，準用何項規定？",
 ["準用儲存相關設備四周五公尺禁煙火、閥操作措施、修理清掃作業及加熱方式等規定","準用境界警戒標示、材料選用、耐壓氣密試驗及壓力表安全裝置等一系列之規定","準用毒性氣體之除毒措施、熔接接合、二重管構造及逆流防止裝置等相關規定","準用固定於車輛容器之防波板、高度檢知桿及工作箱距離等一系列相關之規定"],"a",
 "第192條：一般液化石油氣之消費除依第190條至第191條之1規定外，準用第169條、第172條、第173條及第180條之規定，即儲存相關設備四周五公尺以內嚴禁煙火且不得置放危險性物質、閥或旋塞之適當操作措施、修理等相關作業之置換與盲板阻隔、加熱應使用熱濕布或攝氏四十度以下溫水。",
 "Besides Articles 190 to 191-1, which rules apply to the consumption of general LPG?",
 ["The five-metre no-flame rule, valve operating measures, repair and cleaning work, and the heating method rule","Boundary warning signs, material selection, pressure and airtightness tests and pressure gauge safety devices","Detoxification measures for toxic gases, welded joints, double-pipe construction and backflow prevention","Baffle plates, height detection poles and tool box clearances for containers mounted on transport vehicles"],
 "Article 192 lists the provisions applied by reference."),

(HG,"第193條",3,"高壓氣體-冷凍機器",
 "冷凍機器之冷媒設備所使用之容器，其材料選用及檢查有何規定？何者除外？",
 ["應因應設計壓力與設計溫度採用適當材料，並經認可之超音波探傷檢查合格；未滿二十公噸者除外","應一律採用低溫用高強度合金鋼，並經認可之放射線檢查全長合格；未滿五公噸者除外","應因應常用壓力與常用溫度採用標準材料，並經認可之磁粉探傷試驗合格；未滿十公噸者除外","應因應最高使用壓力採用不鏽鋼材料，並經認可之浸透探傷試驗合格；未滿三公噸者除外"],"a",
 "第193條：冷凍機器之冷媒設備（除一日之冷凍能力未滿二十公噸者外）所使用之容器（除與泵或壓縮機相關者外），其材料應因應該容器之設計壓力、設計溫度等採用適當之材料，且應經中央主管機關認可實施之超音波探傷檢查合格者。第194條並定胴板、端板、蓋板或管板之厚度應適應設計壓力、形狀尺寸、材料種類及熔接接頭效率等。",
 "What material and inspection rules apply to containers of refrigeration machinery refrigerant equipment, and what is excluded?",
 ["Materials suited to design pressure and temperature, passing approved ultrasonic testing; under 20 tonnes excluded","Low-temperature high-strength alloy steel only, passing approved full-length radiography; under 5 tonnes excluded","Standard materials suited to working pressure and temperature, passing magnetic particle tests; under 10 tonnes out","Stainless steel suited to the maximum working pressure, passing approved penetrant testing; under 3 tonnes out"],
 "Article 193; see also Article 194."),

(HG,"第194條",2,"高壓氣體-冷凍機器",
 "冷凍機器容器之胴板、端板、蓋板或管板之厚度，應適應何項因素？",
 ["應適應該容器之設計壓力、形狀及尺寸、材料種類、熔接接頭之有無或熔接接頭之效率等","應適應該容器之常用壓力、使用年限、操作頻率、檢查週期之長短或保養紀錄之完整等","應適應該容器之最高使用壓力、外觀顏色、標示位置、製造廠牌之優劣或價格高低等","應適應該容器之耐壓試驗值、運輸距離、儲存場所、氣候條件之變化或日照時數等"],"a",
 "第194條：容器之胴板、端板、蓋板或管板之厚度，應適應該容器之設計壓力、形狀及尺寸、材料種類、熔接接頭之有無或熔接接頭之效率等。第197條並定在胴板、端板或蓋板開啟之孔應適應板厚、孔徑等，必要時應以補強材補強。",
 "What factors must the thickness of shell, end, cover or tube plates of refrigeration containers suit?",
 ["The design pressure, shape and dimensions, material type, and presence or efficiency of welded joints","The working pressure, service life, operating frequency, inspection interval, and completeness of records","The maximum working pressure, exterior colour, marking position, and brand quality or price level","The hydrostatic test value, transport distance, storage location, climate variation and hours of sunshine"],
 "Article 194; compare Article 197."),

(HG,"第195條",1,"高壓氣體-冷凍機器",
 "冷凍機器容器之熔接，應如何實施？",
 ["應適應接頭之種類，以適當方法實施","應由持證熔接人員以電弧焊接實施","應於工廠內以自動熔接機全數實施","應於現場以氣體熔接方式全程實施"],"a",
 "第195條：容器之熔接，應適應接頭之種類，以適當方法實施。第196條並定容器之熔接部（熔著金屬部分及承受熔接熱影響致材質變化之母材部分）應具有與母材同等以上之強度；第198條規定熔接部應消除應力，但依母材材質厚度、熔接方法、預熱溫度等被認無須者不在此限。",
 "How must welding of refrigeration machinery containers be performed?",
 ["By suitable methods matched to the type of joint","By certified welders using electric arc welding only","Entirely by automatic welding machines in the factory","Entirely by gas welding methods carried out on site"],
 "Article 195; see also Articles 196 and 198."),

(HG,"第196條",2,"高壓氣體-冷凍機器",
 "冷凍機器容器之熔接部，其強度應如何？所稱熔接部範圍為何？",
 ["應具有與母材同等以上之強度；含熔著金屬部分及受熔接熱影響致材質變化之母材部分","應具有母材二倍以上之強度；僅含熔著金屬部分，不包括受熱影響之母材部分在內","應具有母材二分之一以上強度；僅含補強材部分，不包括熔著金屬與母材部分在內","應具有與補強材相同之強度；含容器全部板材，不區分熔接部與非熔接部之範圍"],"a",
 "第196條：容器之熔接部（謂熔著金屬部分及承受熔接之熱影響而致材質產生變化之母材部分），應具有與母材同等以上之強度。第199條並定對頭熔接部應實施接頭拉伸試驗、自由彎曲試驗、側面彎曲試驗、反面彎曲試驗及衝擊試驗合格。",
 "What strength must welds of refrigeration containers have, and what does the weld zone cover?",
 ["Strength equal to or above the base metal; covering deposited metal and heat-affected base metal","Strength at least twice the base metal; covering only deposited metal, not heat-affected metal","Strength at least half the base metal; covering only reinforcing material, not deposited metal","Strength equal to the reinforcing material; covering all plates without distinguishing welds"],
 "Article 196; see also Article 199."),

(HG,"第197條",2,"高壓氣體-冷凍機器",
 "在冷凍機器容器之胴板、端板或蓋板開啟之孔，應如何處理？",
 ["應適應其板厚、孔徑等，必要時應以補強材補強","應適應其材質、顏色等，必要時應以塗裝加以標示","應適應其壓力、溫度等，必要時應以絕熱材料被覆","應適應其位置、方向等，必要時應以盲板加以封閉"],"a",
 "第197條：在容器之胴板、端板或蓋板開啟之孔，應適應其板厚、孔徑等，必要時應以補強材補強。第194條並定板厚應適應設計壓力、形狀及尺寸、材料種類與熔接接頭效率等；第196條定熔接部應具與母材同等以上強度。",
 "How must openings in the shell, end or cover plates of a refrigeration container be treated?",
 ["Suited to plate thickness and hole diameter, reinforced with reinforcing material where necessary","Suited to material and colour, marked with painted identification where this is considered necessary","Suited to pressure and temperature, covered with heat-insulating material where this is necessary","Suited to position and direction, closed off with blind plates where this is considered necessary"],
 "Article 197; compare Articles 194 and 196."),

(HG,"第198條",2,"高壓氣體-冷凍機器",
 "冷凍機器容器之熔接部，對應力有何規定？何者不在此限？",
 ["熔接部應消除應力；依母材材質厚度、熔接方法、預熱溫度等被認無須實施者除外","熔接部應施加預應力；依容器形狀尺寸、使用年限、檢查週期等被認無須者除外","熔接部應實施硬度試驗；依熔接人員資格、施工場所等被認無須實施者除外","熔接部應塗布防鏽塗料；依容器使用環境、儲存場所等被認無須實施者除外"],"a",
 "第198條：容器之熔接部應消除應力；但依母材之材質或厚度、熔接方法、預熱溫度等，被認無須實施消除應力者，不在此限。第195條定熔接應適應接頭種類以適當方法實施；第196條定熔接部應具與母材同等以上之強度。",
 "What rule applies to stress in welds of refrigeration containers, and what is excepted?",
 ["Welds must be stress relieved; excepted where base metal, thickness, method or preheat make it unnecessary","Welds must be prestressed; excepted where container shape, service life or inspection interval make it so","Welds must undergo hardness testing; excepted where welder qualifications or worksite make it unnecessary","Welds must be coated with anti-rust paint; excepted where use environment or storage makes it unnecessary"],
 "Article 198; compare Articles 195 and 196."),

(HG,"第199條",3,"高壓氣體-冷凍機器",
 "冷凍機器容器實施對頭熔接之熔接部，應實施哪些試驗合格？",
 ["接頭拉伸試驗、自由彎曲試驗、側面彎曲試驗、反面彎曲試驗及衝擊試驗","接頭壓縮試驗、扭轉試驗、疲勞試驗、潛變試驗及硬度試驗等五種試驗","接頭剪力試驗、落錘試驗、爆破試驗、氣密試驗及耐壓試驗等五種試驗","接頭腐蝕試驗、鹽霧試驗、超音波試驗、放射線試驗及磁粉試驗等五種"],"a",
 "第199條：容器之實施對頭熔接之熔接部，應依中央主管機關規定實施接頭拉伸試驗、自由彎曲試驗、側面彎曲試驗、反面彎曲試驗及衝擊試驗合格者。第200條至第204條並另定放射線檢查、超音波探傷檢查、磁粉探傷試驗及浸透探傷試驗之要求。",
 "Which tests must butt-welded joints of refrigeration containers pass?",
 ["Joint tensile, free bend, side bend, reverse bend and impact tests","Joint compression, torsion, fatigue, creep and hardness testing","Joint shear, drop weight, burst, airtightness and pressure testing","Joint corrosion, salt spray, ultrasonic, radiographic and magnetic"],
 "Article 199; Articles 200 to 204 add non-destructive testing."),

(HG,"第200條",2,"高壓氣體-冷凍機器",
 "使用對頭熔接之熔接部中，經中央主管機關指定者，應如何檢查？",
 ["應對其全長依中央主管機關規定之方法實施放射線檢查","應對其百分之二十長度依規定之方法實施放射線檢查","應對其全長依中央主管機關規定方法實施磁粉探傷試驗","應對其百分之五十長度依規定之方法實施超音波探傷"],"a",
 "第200條：使用對頭熔接之熔接部中，經中央主管機關指定者，應對其全長依中央主管機關規定之方法實施放射線檢查。第201條則定前條以外之對頭熔接部，應以同一熔接方法及同一條件之每一熔接部，就其全長之百分之二十以上長度實施放射線檢查。",
 "How must butt welds designated by the central competent authority be inspected?",
 ["Radiographic inspection over their full length by the prescribed method","Radiographic inspection over twenty percent of length by the method","Magnetic particle testing over their full length by the prescribed method","Ultrasonic testing over fifty percent of their length by the method"],
 "Article 200; compare Article 201."),

(HG,"第201條",3,"高壓氣體-冷凍機器",
 "非經指定之對頭熔接部，應就其全長之多少長度實施放射線檢查？何者不在此限？",
 ["百分之二十以上長度；設計上無須實施或僅自外面承受壓力之熔接部除外","百分之五十以上長度；設計上無須實施或僅自內面承受壓力之熔接部除外","百分之十以上之長度；經超音波探傷檢查合格或已消除應力之熔接部除外","百分之百之全長長度；經磁粉探傷試驗合格或已補強之熔接部得予以免除"],"a",
 "第201條：第200條規定熔接部以外之對頭熔接部，應以同一熔接方法及同一條件之每一熔接部，就其全長之百分之二十以上長度實施放射線檢查；但設計上被認無須實施放射線檢查或僅自其外面承受壓力之熔接部，不在此限。第200條所指定者則須全長實施。",
 "For non-designated butt welds, what proportion of length needs radiography, and what is excepted?",
 ["At least 20 percent of full length; welds designed as unnecessary or pressured only from outside excepted","At least 50 percent of full length; welds designed as unnecessary or pressured only from inside excepted","At least 10 percent of full length; welds passing ultrasonic testing or already stress relieved excepted","The entire full length in all cases; welds passing magnetic testing or already reinforced are excepted"],
 "Article 201, read with Article 200."),

(HG,"第202條",2,"高壓氣體-冷凍機器",
 "中央主管機關指定之冷凍機器容器之熔接部，應經何種檢查合格？",
 ["應經中央主管機關規定之超音波探傷檢查合格","應經中央主管機關規定之全長放射線檢查合格","應經中央主管機關規定之接頭拉伸試驗合格","應經中央主管機關規定之常用壓力耐壓試驗"],"a",
 "第202條：中央主管機關指定之容器之熔接部，應經中央主管機關規定之超音波探傷檢查合格。第203條並定指定容器之熔接部應就其全長實施磁粉探傷試驗合格；第204條則定實施磁粉探傷困難者應實施浸透探傷試驗。第193條對容器材料亦要求超音波探傷檢查合格。",
 "What inspection must welds of containers designated by the authority pass?",
 ["Ultrasonic testing prescribed by the central competent authority","Full-length radiographic inspection prescribed by the authority","Joint tensile testing prescribed by the central competent authority","A hydrostatic test at normal working pressure set by the authority"],
 "Article 202; compare Articles 193, 203 and 204."),

(HG,"第203條",2,"高壓氣體-冷凍機器",
 "中央主管機關指定之冷凍機器容器之熔接部，應就其全長實施何種試驗？",
 ["應就其全長依規定之方法實施磁粉探傷試驗合格","應就其全長依規定之方法實施浸透探傷試驗合格","應就其全長依規定之方法實施超音波探傷合格","應就其全長依規定之方法實施接頭衝擊試驗合格"],"a",
 "第203條：中央主管機關指定之容器之熔接部，應就其全長依中央主管機關規定之方法就其全長實施磁粉探傷試驗合格。第204條並定該熔接部及以耐蝕、耐熱合金及其他可因熔接而易生缺陷之金屬為母材之熔接部中，被認實施磁粉探傷試驗為困難者，應依規定實施浸透探傷試驗。",
 "What test must welds of containers designated by the authority undergo over their full length?",
 ["Magnetic particle testing over the full length by the prescribed method","Penetrant testing over the full length by the prescribed method used","Ultrasonic testing over the full length by the prescribed method used","Joint impact testing over the full length by the prescribed method used"],
 "Article 203; compare Article 204."),

(HG,"第204條",3,"高壓氣體-冷凍機器",
 "哪些熔接部於實施磁粉探傷試驗有困難時，應改實施浸透探傷試驗？",
 ["指定容器之熔接部及以耐蝕耐熱合金等因熔接易生缺陷金屬為母材之熔接部","僅限指定容器之對頭熔接部，其他熔接部一律免除任何非破壞檢驗之要求","僅限以碳鋼為母材且板厚超過五十毫米之熔接部，其餘一律實施放射線檢查","僅限現場組裝之熔接部，工廠內熔接者一律以超音波探傷檢查代替之處理"],"a",
 "第204條：第203條之熔接部及耐蝕、耐熱合金及其他可因熔接而易生缺陷之金屬為母材之熔接部者中，被認實施磁粉探傷試驗為困難者，應依中央主管機關之規定實施浸透探傷試驗。磁粉探傷對非磁性材料不適用，故以浸透探傷試驗替代。",
 "Which welds must undergo penetrant testing when magnetic particle testing is difficult?",
 ["Welds of designated containers and welds whose base metal is corrosion or heat resistant alloy prone to defects","Only butt welds of designated containers, all other welds being exempt from any non-destructive examination","Only welds with carbon steel base metal over fifty millimetres thick, all others undergoing radiography instead","Only welds assembled on site, all factory welds being replaced by ultrasonic testing as an alternative method"],
 "Article 204, read with Article 203."),

(HG,"第205條",3,"高壓氣體-冷凍機器",
 "冷凍機器之冷媒設備，其氣密試驗及耐壓試驗之壓力各為何？",
 ["以設計壓力以上之壓力實施氣密試驗；配管以外部分以設計壓力一．五倍以上實施耐壓試驗","以設計壓力一．五倍以上之壓力實施氣密試驗；配管以外部分以設計壓力以上實施耐壓試驗","以常用壓力以上之壓力實施氣密試驗；配管以外部分以常用壓力二倍以上實施耐壓試驗","以最高使用壓力二倍之壓力實施氣密試驗；配管以外部分以最高使用壓力三倍實施耐壓"],"a",
 "第205條：冷凍機器應就冷媒設備以設計壓力以上之壓力實施氣密試驗；其配管以外之部分，應以設計壓力一．五倍以上之壓力實施耐壓試驗。第42條對冷媒設備則以最高使用壓力為基準；第41條對高壓氣體設備以常用壓力為基準。第207條並定冷媒設備之材料及構造應適合第205條及第206條規定。",
 "What pressures apply to airtightness and hydrostatic tests of refrigeration machinery refrigerant equipment?",
 ["Airtightness at or above design pressure; parts other than piping hydrostatic at 1.5 times design pressure","Airtightness at 1.5 times design pressure; parts other than piping hydrostatic at or above design pressure","Airtightness at or above normal working pressure; parts other than piping hydrostatic at twice that pressure","Airtightness at twice maximum working pressure; parts other than piping hydrostatic at three times that"],
 "Article 205; compare Articles 41 and 42."),

(HG,"第206條",2,"高壓氣體-冷凍機器",
 "冷凍機器之冷媒設備，應具有何種性能？",
 ["應具有可防止振動、衝擊、腐蝕等致使冷媒氣體外洩者","應具有可防止日照、雨水、積雪等致使冷媒氣體結冰者","應具有可承受地震影響並防止基礎不均勻沈陷之耐震者","應具有可防止靜電、火花、雷擊等致使冷媒氣體著火者"],"a",
 "第206條：冷凍機器之冷媒設備，應具有可防止振動、衝擊、腐蝕等致使冷媒氣體外洩者。第40條對冷凍用高壓氣體之製造設備有相同要求；第207條並定冷媒設備（除第193條至第204條規定之容器外）之材料及構造應適合第205條及第206條之規定。",
 "What performance must refrigeration machinery refrigerant equipment provide?",
 ["It must prevent refrigerant leakage caused by vibration, impact or corrosion","It must prevent refrigerant freezing caused by sunlight, rain or accumulated snow","It must resist earthquakes and prevent uneven settlement of its own foundation","It must prevent refrigerant ignition caused by static, sparks or lightning strikes"],
 "Article 206; identical to Article 40."),

(HG,"第207條",2,"高壓氣體-冷凍機器",
 "冷凍機器之冷媒設備中，除受容器規定規範者外，其材料及構造應適合何項規定？",
 ["應適合氣密與耐壓試驗壓力規定，及防止振動衝擊腐蝕致冷媒外洩之規定","應適合超音波探傷檢查與放射線檢查規定，及熔接部消除應力之相關規定","應適合材料選用與板厚計算規定，及開孔應以補強材補強之相關各項規定","應適合接頭拉伸試驗與彎曲試驗規定，及磁粉浸透探傷試驗之相關規定"],"a",
 "第207條：冷凍機器之冷媒設備（除第193條至第204條規定之容器外）之材料及構造，應適合第205條及前條之規定者，即以設計壓力以上實施氣密試驗、配管以外部分以設計壓力一．五倍以上實施耐壓試驗，並應具有可防止振動、衝擊、腐蝕等致使冷媒氣體外洩之性能。",
 "For refrigerant equipment other than the regulated containers, what must the materials and construction satisfy?",
 ["The airtightness and hydrostatic test pressure rules, and the rule preventing leakage from vibration or corrosion","The ultrasonic and radiographic inspection rules, and the rule requiring stress relief of the welded joints","The material selection and plate thickness rules, and the rule requiring openings to be reinforced properly","The joint tensile and bend testing rules, and the rules on magnetic particle and penetrant testing methods"],
 "Article 207, applying Articles 205 and 206."),

(HG,"第208條",2,"高壓氣體-特殊標準",
 "中央主管機關對高壓氣體之製造，認定製造事業單位設施情況特殊者，得如何處理？",
 ["得使其不受第二章製造安全設施規定之限制，另以適當標準為製造設施標準","得使其不受第四章儲存安全設施規定之限制，另以適當標準為儲存設施標準","得使其免除全部安全設施規定，改由目的事業主管機關逕行核定其設施內容","得使其延長改善期限至五年，期間內不受任何安全設施規定之限制與處分"],"a",
 "第208條：中央主管機關對高壓氣體之製造，依各該氣體之種類、製造設施之規模、事業場所四周環境之狀況、製造方法及其他相關事項，認定製造事業單位之設施情況特殊，得使其不受第二章規定之限制，另以適當標準為製造設施標準。第209條對高壓氣體之儲存亦有相對應之規定，得不受第四章規定之限制。第242條定本條不適用於液化石油氣。",
 "Where the authority finds a manufacturer facility situation special, what may it do?",
 ["Exempt it from Chapter 2 manufacturing safety rules and set suitable manufacturing facility standards instead","Exempt it from Chapter 4 storage safety rules and set suitable storage facility standards for it instead","Exempt it from all safety facility rules, leaving the sector authority to approve the facility content","Extend its improvement period to five years, free from any safety facility rules or penalties meanwhile"],
 "Article 208; Article 209 does the same for storage."),

(HG,"第209條",2,"高壓氣體-特殊標準",
 "中央主管機關對高壓氣體之儲存，認定儲存設施情況特殊者，得如何處理？",
 ["得使其不受第四章儲存安全設施規定之限制，另以適當標準為儲存設施標準","得使其不受第二章製造安全設施規定之限制，另以適當標準為製造設施標準","得使其免除全部安全設施規定，改由目的事業主管機關逕行核定其設施內容","得使其延長改善期限至五年，期間內不受任何安全設施規定之限制與處分"],"a",
 "第209條：中央主管機關對高壓氣體之儲存，依各該氣體之種類、高壓氣體儲存場所之規模、儲存場所四周環境之狀況、儲存方法及其他相關事項，認定高壓氣體儲存場所之儲存設施情況特殊，得使其不受第四章規定之限制，另以適當標準為儲存設施標準。第208條則為製造設施之相對應規定。",
 "Where the authority finds a storage facility situation special, what may it do?",
 ["Exempt it from Chapter 4 storage safety rules and set suitable storage facility standards for it instead","Exempt it from Chapter 2 manufacturing safety rules and set suitable manufacturing standards instead","Exempt it from all safety facility rules, leaving the sector authority to approve the facility content","Extend its improvement period to five years, free from any safety facility rules or penalties meanwhile"],
 "Article 209; Article 208 does the same for manufacturing."),

(HG,"第211條",2,"高壓氣體-廢棄",
 "可燃性氣體之廢棄，對場所及排放方式有何規定？",
 ["不得近接煙火處置場所或放置危險性物質場所及其附近；排放於大氣時應於通風良好場所緩緩排放","不得近接住宅區或學校醫院等場所及其附近；排放於大氣時應於密閉容器內迅速一次排放完畢","不得近接水源保護區或河川出海口及其附近；排放於大氣時應於低窪處所以水霧沖淡後排放","不得近接電力設施或變電所等場所及其附近；排放於大氣時應於夜間以加壓方式快速排放"],"a",
 "第211條：可燃性氣體之廢棄，不得近接於煙火之處置場所或放置有危險性物質之場所及其附近場所為之；排放於大氣中時，應於通風良好之場所緩緩排放。第210條並定可燃性氣體等不得併同容器廢棄；第213條規定連續廢棄可燃性氣體或毒性氣體時應檢測滯留濃度並採適當措施。",
 "What rules govern the place and manner of discarding flammable gas?",
 ["Not near places handling flames or holding dangerous substances; when released to air, slowly in a well-ventilated place","Not near residential areas or schools and hospitals nearby; when released to air, rapidly and at once in a closed vessel","Not near water source protection zones or river mouths nearby; when released to air, in low ground diluted by water mist","Not near power facilities or substations and their vicinity; when released to air, rapidly at night under pressurisation"],
 "Article 211; compare Articles 210 and 213."),

(HG,"第212條",1,"高壓氣體-廢棄",
 "排放毒性氣體於大氣中時，應依何規定辦理？",
 ["應依環境保護有關規定辦理","應依消防法有關規定辦理","應依建築管理法規規定辦理","應依交通運輸法規規定辦理"],"a",
 "第212條：排放毒性氣體於大氣中時，應依環境保護有關規定。第211條對可燃性氣體之排放定應於通風良好場所緩緩排放；第213條規定連續廢棄可燃性氣體或毒性氣體時，應檢測各該氣體之滯留濃度並採取適當之措施。第242條定本條不適用於液化石油氣。",
 "Under what law must toxic gas be released into the atmosphere?",
 ["Under the relevant environmental protection provisions","Under the relevant provisions of the Fire Services Act","Under the relevant building administration regulations","Under the relevant transport and traffic regulations"],
 "Article 212; compare Articles 211 and 213."),

(HG,"第213條",2,"高壓氣體-廢棄",
 "連續廢棄可燃性氣體或毒性氣體時，應如何辦理？",
 ["應檢測各該氣體之滯留濃度，並採取適當之措施","應檢測各該氣體之排放流量，並填具申報表備查","應檢測各該氣體之容器壓力，並記錄保存三年備查","應檢測各該氣體之純度與色澤，並張貼標示於容器"],"a",
 "第213條：連續廢棄可燃性氣體或毒性氣體時，應檢測各該氣體之滯留濃度，並採取適當之措施。第211條、第212條分別規定可燃性氣體與毒性氣體之排放方式；第60條、第167條並定有漏洩積滯之虞場所應設氣體漏洩檢知警報設備。",
 "What must be done when flammable or toxic gas is discarded continuously?",
 ["Measure the accumulated concentration of each gas and take suitable measures","Measure the discharge flow rate of each gas and file a declaration form for record","Measure the container pressure of each gas and keep the records for three years","Measure the purity and colour of each gas and attach a label on each container"],
 "Article 213; compare Articles 60, 167, 211 and 212."),

(HG,"第214條",2,"高壓氣體-廢棄",
 "氧氣之廢棄所使用之閥或器具，應如何處理後始得使用？",
 ["非除卻石油類、油脂類及其他可燃性氣體後，不得使用","非以氮氣或二氧化碳置換其內部氣體後，不得使用","非經實施音響檢查及容器內部檢查後，不得使用","非以熱濕布或攝氏四十度以下溫水加熱後，不得使用"],"a",
 "第214條：氧氣之廢棄所使用之閥或器具，非除卻石油類、油脂類及其他可燃性氣體後，不得使用。第185條對氧氣之消費、第170條對液氧之消費、第97條第二款對灌注氧氣於容器均有相同之除卻石油類油脂類要求。第242條定本條不適用於液化石油氣。",
 "How must valves or appliances used for discarding oxygen be treated before use?",
 ["They may not be used until petroleum, oils and fats and other combustible gases are removed","They may not be used until their interior has been purged with nitrogen or carbon dioxide","They may not be used until they have passed a sound check and an internal inspection","They may not be used until warmed with hot wet cloth or warm water at or below 40 C"],
 "Article 214; compare Articles 97, 170 and 185."),

(HG,"第215條",2,"高壓氣體-廢棄",
 "可燃性氣體、毒性氣體及氧氣於廢棄後，應如何處理？",
 ["應嚴閉其閥，並採取防止容器翻倒及損傷其閥之措施","應開啟其閥洩壓，並採取容器分區放置與標示之措施","應以氮氣置換內部，並採取容器加鎖及鉛封之措施","應立即送回供應事業單位，並採取運輸檢點之措施"],"a",
 "第215條：可燃性氣體等應於廢棄後嚴閉其閥，並採取防止容器翻倒及損傷其閥之措施。第186條對消費後亦有完全相同之規定；第210條並定可燃性氣體等不得併同容器廢棄。",
 "What must be done after flammable, toxic or oxygen gas has been discarded?",
 ["Close the valves tightly and take measures preventing the container toppling or valve damage","Open the valves to release pressure and take measures for separate placement and marking","Purge the interior with nitrogen and take measures locking and lead-sealing the containers","Return them to the supply enterprise at once and take transport inspection measures first"],
 "Article 215; identical to Article 186."),

(HG,"第216條",2,"高壓氣體-廢棄",
 "廢棄作業中灌氣容器等之閥類，應準用何項規定？",
 ["準用考慮閥之材料構造使用狀況以防止過巨之力加諸於閥上並訂入工作守則之規定","準用容器應保持溫度攝氏四十度以下並設溫度計或可檢知溫度計測裝置之規定","準用配管應採熔接接合並依氣體性狀於必要處所採二重管構造之相關各項規定","準用容器不得有腐蝕裂隙裂痕皺紋且應無漏氣並標示有效期限之相關各項規定"],"a",
 "第216條：灌氣容器等之閥類，準用第175條之規定，即操作時應考慮該閥之材料、構造及使用狀況，採取必要之措施以防止過巨之力加諸於閥上，並訂入工作守則中。第179條對消費作業中可燃性氣體等灌氣容器之閥亦準用第175條。第242條定本條不適用於液化石油氣。",
 "Which rule applies by reference to valves of filled cylinders during discarding operations?",
 ["The rule on considering valve material, construction and condition to avoid excessive force, written into work rules","The rule on keeping container temperature at or below 40 degrees with a thermometer or measuring device fitted","The rule on welding piping joints and using double-pipe construction where the gas properties require it","The rule on cylinders being free of corrosion, cracks and leaks and carrying a validity period marking"],
 "Article 216, applying Article 175."),

(HG,"第217條",2,"高壓氣體-廢棄",
 "廢棄作業中加熱於灌氣容器等、閥或配管時，應使用何種方式？",
 ["應使用熱濕布或溫度在攝氏四十度以下之溫水","應使用蒸汽管或溫度在攝氏一百度以下之熱水","應使用電熱毯或溫度在攝氏六十度以下之溫風","應使用紅外線燈或溫度在攝氏八十度以下熱媒"],"a",
 "第217條：加熱於灌氣容器等、閥或配管時，應使用熱濕布或溫度在攝氏四十度以下之溫水。第180條對消費作業、第97條第三款對乙類製造事業單位之製造作業、第78條第六款對霧劑製造均有相同之熱濕布或攝氏四十度以下溫水規定。",
 "How may filled cylinders, valves or piping be heated during discarding operations?",
 ["With hot wet cloth or with warm water at or below 40 degrees Celsius","With steam piping or with hot water at or below 100 degrees Celsius","With an electric blanket or with warm air at or below 60 degrees Celsius","With an infrared lamp or with heat medium at or below 80 degrees Celsius"],
 "Article 217; compare Articles 78, 97 and 180."),

(HG,"第220條",3,"高壓氣體-安全管理",
 "哪些甲類製造事業單位應於製造開始之日選任高壓氣體製造安全主任？其任務與訓練要求為何？",
 ["液化石油氣、冷凍用高壓氣體以外之甲類事業單位；輔助製造安全負責人並應受安全主任訓練","液化石油氣及冷凍用高壓氣體之甲類事業單位；綜理製造安全業務並應受作業主管訓練","全部甲類及乙類製造事業單位；負責指揮監督勞工作業並應受製造安全規劃人員訓練","僅一日製造容積一百萬立方公尺以上者；規劃安全教育計畫並應受消費作業主管訓練"],"a",
 "第220條：液化石油氣、冷凍用高壓氣體製造事業單位以外之甲類製造事業單位，應於製造開始之日，依各該事業製程狀況，按第221條規定分別選任高壓氣體製造安全主任，輔助高壓氣體製造安全負責人從事製造安全技術管理事務；並應依職業安全衛生教育訓練規則接受高壓氣體製造安全主任安全衛生教育訓練。第219條則規定製造安全負責人之指派與報備。",
 "Which Class A enterprises must appoint a high-pressure gas manufacturing safety officer, with what role and training?",
 ["Class A units other than LPG and refrigeration ones; assisting the safety principal and taking safety officer training","Class A units engaged in LPG and refrigeration gas; managing all safety affairs and taking supervisor training","All Class A and Class B manufacturing enterprises; directing workers and taking safety planner training","Only those producing a million cubic metres a day; planning safety education and taking consumption training"],
 "Article 220; compare Article 219."),

(HG,"第221條",2,"高壓氣體-安全管理",
 "甲類製造事業單位應於何時選任高壓氣體製造安全作業主管？其選任依據及訓練要求為何？",
 ["應於製造設備設置之日，依高壓氣體之製造種類分別選任；並應接受作業主管安全衛生教育訓練","應於製造開始之日，依事業單位之資本額大小分別選任；並應接受安全主任安全衛生教育訓練","應於勞動檢查機構通知之日，依勞工人數多寡分別選任；並應接受安全負責人之專業教育訓練","應於發生災害之日，依災害嚴重程度分別選任；並應接受規劃人員之在職進修與複訓等課程"],"a",
 "第221條：第220條之甲類製造事業單位，應於該條表所定製造設備設置之日，依高壓氣體之製造種類，分別選任高壓氣體製造安全作業主管；擔任者應依職業安全衛生教育訓練規則規定，接受高壓氣體製造安全作業主管安全衛生教育訓練。第224條並定其應維持製造設備符合法令基準、監督實施自動檢查、實施巡視與檢點等職責。",
 "When must a Class A enterprise appoint a manufacturing safety supervisor, on what basis, and with what training?",
 ["On the day the manufacturing equipment is installed, by type of gas manufactured; supervisor safety training required","On the day manufacturing starts, by the amount of the capital of the enterprise; safety officer training required","On the day the labour inspection agency gives notice, by the number of workers; safety principal training required","On the day a disaster occurs, by the severity of the disaster concerned; planner refresher training required"],
 "Article 221; see also Article 224 on duties."),

(HG,"第222條",3,"高壓氣體-安全管理",
 "選任高壓氣體製造安全作業主管時，何種情形之製造設備得歸納於同一種類？",
 ["表列第一款至第十七款設備與第十八款設備相鄰接且配置一體管理，並於同一計器室控制或安全管理具同等功能","表列全部十八款設備不論是否相鄰接，只要屬同一事業單位所有且由同一負責人管理即得歸納於同一種類","表列設備之處理能力合計未滿一百立方公尺，且經勞動檢查機構核准者，即得歸納於同一種類辦理","表列設備之操作人員採用輪班制，且各班次人數相同者，即得歸納於同一種類並由一人擔任主管"],"a",
 "第222條：依第221條選任高壓氣體製造安全作業主管時，該條表列第一款至第十七款所列之一種或二種以上之製造設備與同表第十八款所列之一種或二種以上之製造設備相鄰接，且其配置設計為一體實施管理，並於同一計器室內控制其操作，或在安全管理具有同等功能者，該製造設備等可歸納於同一種類；對同一高壓氣體製造種類內之二種以上之製造設備亦同。",
 "When may manufacturing equipment be grouped as one type for appointing a manufacturing safety supervisor?",
 ["Items 1 to 17 adjoin items 18, are laid out for integrated management, and are controlled in one instrument room or equivalent","All eighteen listed items regardless of adjacency, provided they belong to one enterprise under one responsible person","The listed equipment has combined processing capacity under 100 cubic metres and the inspection agency approves it","The operators of the listed equipment work in shifts and each shift has the same number of workers assigned to it"],
 "Article 222 sets the grouping conditions."),

(HG,"第223條",3,"高壓氣體-安全管理",
 "依第二百二十一條選任作業主管時，哪些情形之設備得歸納於同一類？操作採輪班制者又如何？",
 ["處理能力一百立方公尺以下、以氣化器減壓閥製氧氮氬氦、以氣化器製二氧化碳者；輪班制應分別選任","處理能力三百立方公尺以下、以壓縮機製可燃性氣體、以冷凍設備製液氧者；輪班制得合併選任一人","處理能力一千立方公尺以下、以導管輸送原料氣體、以儲槽儲存毒性氣體者；輪班制免予選任主管","處理能力五十立方公尺以下、以容器灌裝液化石油氣、以加氣站灌裝車輛者；輪班制由負責人兼任"],"a",
 "第223條：設備之任一設備以外之設備之全部適於下列規定之一者得歸納同一類：一、處理設備之處理能力在一百立方公尺以下時（設有可燃性氣體之液化氣體加壓泵者除外）。二、使用氣化器或減壓閥製造氧氣、氮氣、氬氣或氦氣之製造設備時。三、使用氣化器製造二氧化碳之製造設備。另製造設備之操作由二以上系列形成且非於同一計器室控制，或操作人員採輪班制時，應依操作控制系列或依班次分別選任作業主管。",
 "Which equipment may be grouped as one class, and what applies where operators work shifts?",
 ["Processing capacity 100 m3 or less, vaporiser or reducer for oxygen nitrogen argon helium, vaporiser for CO2; shifts appoint separately","Processing capacity 300 m3 or less, compressors for flammable gas, refrigeration for liquid oxygen; shifts may share one supervisor","Processing capacity 1,000 m3 or less, pipeline transport of raw gas, tank storage of toxic gas; shifts need no supervisor at all","Processing capacity 50 m3 or less, cylinder filling of LPG, filling station work for vehicles; shifts covered by the principal"],
 "Article 223 sets the grouping conditions and the shift rule."),

(HG,"第226條",3,"高壓氣體-安全管理",
 "高壓氣體製造安全規劃人員，輔導製造安全負責人規劃之事項包括下列何者？",
 ["規劃訂定製造安全工作守則、規劃安全教育計畫、規劃防災訓練及災害原因調查與檢討防災對策","負責指揮監督操作人員作業、簽認每日檢點表單、擔任緊急應變指揮官及對外發布新聞稿","代表事業單位向勞動檢查機構申請許可、辦理檢查合格證換發及繳納檢查規費等行政事務","負責高壓氣體之採購與議價、審核供應商資格、簽訂運輸契約及管理容器之進出庫存量"],"a",
 "第226條：製造安全規劃人員輔導製造安全負責人規劃下列事項：一、規劃訂定有關高壓氣體製造安全工作守則。二、規劃安全教育計畫並予推展。三、有關製造安全之基本對策。四、提供作業標準、設備管理基準或承攬管理及防災措施基準之建議並實施指導。五、規劃防災訓練及推展。六、發生災害時之災害原因調查及檢討防災對策。七、蒐集有關製造高壓氣體之資料。第231條對液化石油氣製造安全規劃人員有相同架構之規定。",
 "Which matters does the manufacturing safety planner help the safety principal to plan?",
 ["Drafting safety work rules, planning safety education, planning disaster drills, and investigating causes and countermeasures","Directing and supervising operators, signing daily checklists, acting as emergency commander and issuing press releases","Applying to the labour inspection agency for permits, renewing inspection certificates and paying inspection fees","Purchasing and negotiating gas prices, vetting suppliers, signing transport contracts and managing cylinder stock"],
 "Article 226; compare Article 231 for LPG."),

(HG,"第227條",3,"高壓氣體-液化石油氣",
 "處理能力達多少之液化石油氣甲類製造事業單位，應選任高壓氣體製造安全主任？純供灌裝者門檻為何？",
 ["處理能力一百萬立方公尺以上；設置儲槽純供灌裝者為二百萬立方公尺以上","處理能力五十萬立方公尺以上；設置儲槽純供灌裝者為一百萬立方公尺以上","處理能力三百萬立方公尺以上；設置儲槽純供灌裝者為五百萬立方公尺以上","處理能力十萬立方公尺以上；設置儲槽純供灌裝者為二十萬立方公尺以上"],"a",
 "第227條：處理能力在一百萬立方公尺以上之液化石油氣甲類製造事業單位，應於製造開始之日，依各該事業製程狀況，分別選任高壓氣體製造安全主任，輔助製造安全負責人從事製造安全技術管理事務；設置儲槽純供灌裝液化石油氣之事業單位，前項處理能力為二百萬立方公尺以上。擔任者並應接受高壓氣體製造安全主任安全衛生教育訓練。第225條對非液化石油氣者亦定一百萬與二百萬立方公尺之門檻。",
 "At what processing capacity must a Class A LPG enterprise appoint a manufacturing safety officer, and what applies to pure filling?",
 ["One million cubic metres or more; two million cubic metres or more where tanks are used purely for filling","Five hundred thousand cubic metres or more; one million cubic metres or more where tanks are for filling","Three million cubic metres or more; five million cubic metres or more where tanks are used for filling","One hundred thousand cubic metres or more; two hundred thousand cubic metres or more for pure filling"],
 "Article 227; compare Article 225."),

(HG,"第228條",3,"高壓氣體-液化石油氣",
 "液化石油氣甲類製造事業單位之輸液總量達多少者，應選任高壓氣體製造安全作業主管？氣態如何換算？",
 ["攝氏三十五度時每小時輸液量合計一百六十立方公尺以上；氣態以容積十立方公尺換算輸液量一立方公尺","攝氏三十五度時每小時輸液量合計八十立方公尺以上；氣態以容積五立方公尺換算輸液量一立方公尺","攝氏十五度時每小時輸液量合計三百立方公尺以上；氣態以容積二十立方公尺換算輸液量一立方公尺","攝氏零度時每小時輸液量合計五十立方公尺以上；氣態以容積一百立方公尺換算輸液量一立方公尺"],"a",
 "第228條：第227條之甲類製造事業單位，於溫度在攝氏三十五度時，其處理設備之每小時液化石油氣輸液量之合計量（輸液總量）在一百六十立方公尺以上者，應於該設備設置之日選任高壓氣體製造安全作業主管；輸液總量之計算，對氣體狀態之液化石油氣，應以容積十立方公尺換算為輸液量一立方公尺。擔任者並應接受作業主管安全衛生教育訓練。",
 "At what total liquid transfer volume must an LPG Class A enterprise appoint a safety supervisor, and how is gas converted?",
 ["Hourly transfer totalling 160 cubic metres at 35 C; gaseous LPG converts 10 cubic metres of volume to 1 of transfer","Hourly transfer totalling 80 cubic metres at 35 C; gaseous LPG converts 5 cubic metres of volume to 1 of transfer","Hourly transfer totalling 300 cubic metres at 15 C; gaseous LPG converts 20 cubic metres of volume to 1 transfer","Hourly transfer totalling 50 cubic metres at 0 C; gaseous LPG converts 100 cubic metres of volume to 1 transfer"],
 "Article 228 sets the threshold and the conversion factor."),

(HG,"第229條",2,"高壓氣體-液化石油氣",
 "依第二百二十八條選任之高壓氣體製造安全作業主管，應擔負哪些技術事項？",
 ["維持製造設備及製造方法符合法令基準、監督實施自動檢查、實施巡視與檢點並於災害時採必要措施","核發製造許可與檢查合格證、辦理容器重新檢查、簽署運輸文件並向消防機關辦理危險物品申報","訂定採購規範與驗收標準、審核承攬商報價、辦理保險理賠及編製事業單位年度預算與決算表","負責勞工體格與健康檢查、辦理特殊健康檢查分級管理、指定醫護人員及規劃健康促進活動等"],"a",
 "第229條：依第228條選任之高壓氣體製造安全作業主管，應擔負維持製造設備之安全、監視製造方法與液化石油氣製造有關之下列技術事項並監督指揮勞工作業：一、維持製造設備符合法令規定基準。二、維持製造方法符合法令規定基準。三、監督實施自動檢查。四、實施巡視與檢點。五、對安全作業標準、設備管理基準、承攬管理基準及災害必要措施提供建議。六、於發生災害或有發生災害之虞時立即採取必要措施。第224條對高壓氣體製造安全作業主管有相同架構之規定。",
 "What technical duties does the LPG manufacturing safety supervisor carry?",
 ["Keeping equipment and methods lawful, supervising automatic inspections, patrolling and checking, and acting in a disaster","Issuing manufacturing permits and inspection certificates, re-inspecting containers and filing dangerous goods reports","Setting purchasing specifications, vetting contractor quotes, handling insurance claims and preparing annual budgets","Arranging worker physical and health examinations, grading special health checks and planning health promotion work"],
 "Article 229; compare Article 224."),
]
